import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"CPU 亲和","description":"","frontmatter":{"title":"CPU 亲和","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpu-affinity.md","filePath":"cs/cpu-affinity.md","lastUpdated":1789023840000}'),h={name:"cs/cpu-affinity.md"};function f(u,a,_,m,A,E){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="cpu-亲和" tabindex="-1">CPU 亲和 <a class="header-anchor" href="#cpu-亲和" aria-label="Permalink to &quot;CPU 亲和&quot;">​</a></h1><div class="epigraph"><p>任务的 CPU 掩码限制它能在哪些核上运行；硬亲和保证隔离，软亲和只是迁移启发式不愿离开热缓存。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/edf-sched">上一课</a>让期限调度可以选谁上 CPU，还没说「哪颗」。<a href="/cs/load-balance-migrate">负载均衡</a>默认哪闲迁哪。<a href="/cs/irq-affinity">中断亲和</a>已经把 IRQ 钉到核上。缺口是<strong>任务的 CPU 亲和</strong>：PCB 上的掩码，调度器与迁移不得违反。本课钉硬/软亲和，不把 NUMA 距离写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实时核希望旁边没有分时任务；科学计算希望线程不在 SMT 兄弟之间乱跳。硬亲和：掩码外的核对该任务当不存在，平衡器不能为了闲而搬过去。软亲和：内核记住上次跑过的核，能不迁就不迁，但掩码仍是全体。缺口不是 EDF 的截止比较，而是这道约束。</p><p><span class="marginnote">掩码与 IRQ 亲和应对齐：处理线程若不能跑在收中断的核上，上半部与下半部跨核乒乓。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户或管理接口写 <code>cpuset</code>/<code>sched_setaffinity</code>。唤醒：只在掩码与负载允许的核中选。迁移检查掩码。子进程默认继承。内核线程可绑在某核上跑 per-CPU 工作，与<a href="/cs/percpu">per-CPU 数据</a>一致。</p>',8)),(e(),n(d,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E4%BB%BB%E5%8A%A1%20CPU%20%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20PICK%5B%22%E5%8F%AA%E4%BB%8E%E5%85%81%E8%AE%B8%E6%A0%B8%E9%80%89%20runqueue%22%5D%0A%20%20MASK%20--%3E%20MIG%5B%22%E8%BF%81%E7%A7%BB%E4%B8%8D%E5%BE%97%E8%B6%8A%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>空掩码非法；只剩的核若全部离线，任务会卡住——管理问题，课内承认约束可以过紧。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬亲和把公平与期限的「全局最优」换成「在子集上最优」。隔离实时：分时任务掩码不含隔离核。代价是：子集过热时不能借用外面的 idle，利用率尺子变差。软亲和降低迁移税，与 CFS 的 cache 热度启发式是同一方向。</p><p>与 clone：新线程可另设掩码。不是安全沙箱：亲和不阻止访问内存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 cgroup cpuset 的全部层级写成容器课。也不讨论用户伪造亲和去占核的政策。内存落在哪一节点、迁过去是否更亏，下一课 NUMA 调度。</p><p>后课默认：任务可被钉在 CPU 子集上。访存不对称时还要考虑内存节点，下一课讲 NUMA 调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬亲和：可运行 CPU 集合；软亲和：不愿离开热核。</li><li>与中断亲和应对齐；过紧会浪费 idle。</li><li>NUMA 节点距离是下一课。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const B=o(h,[["render",f]]);export{C as __pageData,B as default};
